      if (yych <= '\t')
        goto yy524;
      if (yych >= '\v')
        goto yy518;
    } else {
      if (yych <= '\r')
        goto yy525;
      if (yych == ' ')
        goto yy524;
      goto yy518;
    }
  yy525:
